/** 内嵌字库覆盖的字（测试据此断言数据没被误删） */
export const STROKE_CHARS: readonly string[] = Object.freeze(Object.keys(STROKE_RAW));

/** 取字形数据；没有就返回 null（调用方负责降级提示） */
export function getHanziData(char: string): HanziData | null {
  return STROKE_RAW[char] ?? null;
}

/** 笔画数；数据缺失时回退 0（界面据此显示"暂无笔顺"） */
export function strokeCount(char: string): number {
  return STROKE_RAW[char]?.strokes.length ?? 0;
}
